from collections import deque
def fill(g, shape=None):
    h,w=len(g),len(g[0])
    cols=set(v for r in g for v in r)
    bg=5 if 5 in cols else 1
    seen=[[False]*w for _ in range(h)]
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and g[a][b]==bg and not seen[a][b]:
                seen[a][b]=True; q.append((a,b))
    return [[2 if g[i][j]==bg and not seen[i][j] else g[i][j] for j in range(w)] for i in range(h)], bg

