def transform(grid):
    g=[row[:] for row in grid]
    from collections import Counter
    cnt=Counter(v for row in g for v in row)
    bg=cnt.most_common(1)[0][0]
    cells=[(i,j) for i,row in enumerate(g) for j,v in enumerate(row) if v!=bg and v!=2]
    if not cells: return g
    shape=Counter(g[i][j] for i,j in cells).most_common(1)[0][0]
    S={(i,j) for i,j in cells if g[i][j]==shape}
    rs=[i for i,j in S]; cs=[j for i,j in S]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    def fill(i,j):
        if g[i][j]==bg: g[i][j]=2
    for j in range(c0,c1+1): fill(r0,j); fill(r1,j)
    for i in range(r0,r1+1): fill(i,c0); fill(i,c1)
    # internal full-length lines: rows/cols with shape cells off the perimeter
    for i in range(r0+1,r1):
        if any((i,j) in S and not (j==c0 or j==c1) for j in range(c0,c1+1)):
            for j in range(c0,c1+1): fill(i,j)
    for j in range(c0+1,c1):
        if any((i,j) in S and not (i==r0 or i==r1) for i in range(r0,r1+1)):
            for i in range(r0,r1+1): fill(i,j)
    return g

